def update_guides_data():
    filepath = "src/data/guides-data.ts"
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    # Find the closing bracket of the guides array
    # The guides array is exported as: export const guides: Guide[] = [ ... ];
    # Let's format the Javascript objects for the new guides

    formatted_guides = []
    for g in october31_guides:
        # Convert python dict to formatted typescript object string
        obj_str = json.dumps(g, indent=2, ensure_ascii=False)
        # Fix keys formatting if needed, but JSON format is valid JS
        formatted_guides.append(obj_str)

    guides_js = ",\n".join(formatted_guides)

    # We want to insert `guides_js` right before the last `];` at the end of the file or the end of the array export.
    idx = content.rfind("];")
    if idx == -1:
        raise Exception("Could not find closing ]; in guides-data.ts")

    new_content = content[:idx].rstrip() + ",\n" + guides_js + "\n];\n"

    with open(filepath, "w", encoding="utf-8") as f:
        f.write(new_content)

    print("Successfully appended 3 new guides to src/data/guides-data.ts")

if __name__ == "__main__":
    update_guides_data()
